// B"H

async function pause(ms) {
  if (!ms) return;
  await new Promise(resolve => setTimeout(resolve, ms));
}

/**
 * B"H
 * Applies simple JSON interactions to a SyntheticBrowserRuntime.
 *
 * @param {object} runtime Runtime containing window.interactions.
 * @param {Array<object>} interactions Declarative interactions.
 * @returns {Promise<Array<object>>} Interaction replay log.
 */
async function applyInteractions(runtime, interactions = []) {
  const log = [];
  const virtual = runtime?.window?.interactions;
  if (!virtual) return log;

  for (const step of interactions) {
    const op = step.op || step.action;
    if (op === "wait") { await pause(Number(step.ms || 0)); continue; }
    if (typeof virtual[op] !== "function") throw new Error("Unsupported interaction: " + op);
    const value = virtual[op](step.selector, step.text ?? step.key ?? step.expected);
    log.push({ op, selector: step.selector || null, ok: true, value });
  }
  return log;
}

module.exports = { applyInteractions };

// B"H

function filesOf(ctx = {}) {
  ctx.options = ctx.options || {};
  ctx.options.files = ctx.options.files || {};
  return ctx.options.files;
}

function record(ctx = {}, entry = {}) {
  ctx.logs = ctx.logs || [];
  const sealed = { at: Date.now(), ...entry };
  ctx.logs.push(sealed);
  return sealed;
}

function syntaxCheckSource(source = "") {
  try {
    Function(String(source));
    return { ok: true };
  } catch (error) {
    return { ok: false, error: error.message, stack: error.stack };
  }
}

/**
 * B"H
 * Builds a tiny data-driven command registry for the Merkava workflow chariot.
 * The Awtsmoos speaks each step into being: virtual files are written, checked,
 * simulated, logged, and carried forward without Chrome or a physical browser.
 *
 * @param {Function} runOnce Runs one normalized virtual runtime pass.
 * @returns {Object<string, Function>} Workflow actions keyed by declarative names.
 */
export function createActionRegistry(runOnce) {
  return {
    async log(ctx = {}, payload = {}) {
      return record(ctx, { kind: "log", message: payload.message || "", value: payload.value ?? ctx.result ?? null });
    },

    async setFile(ctx = {}, payload = {}) {
      const files = filesOf(ctx);
      const path = payload.path || payload.p || payload.file || ctx.entry || "index.js";
      files[path] = String(payload.content ?? "");
      return record(ctx, { kind: "setFile", path, bytes: Buffer.byteLength(files[path], "utf8") });
    },

    async patchFile(ctx = {}, payload = {}) {
      const files = filesOf(ctx);
      const path = payload.path || payload.p || payload.file || ctx.entry || "index.js";
      const before = String(files[path] || "");
      const find = String(payload.find ?? "");
      const replace = String(payload.replace ?? "");
      const after = payload.regex ? before.replace(new RegExp(find, payload.flags || "g"), replace) : before.split(find).join(replace);
      files[path] = after;
      return record(ctx, { kind: "patchFile", path, changed: before !== after });
    },

    async syntaxCheck(ctx = {}, payload = {}) {
      const files = filesOf(ctx);
      const targets = payload.paths || payload.files || [payload.path || payload.p || ctx.entry || "index.js"];
      const results = [].concat(targets).map(path => ({ path, ...syntaxCheckSource(files[path] || "") }));
      const result = { ok: results.every(item => item.ok), action: "syntaxCheck", results };
      record(ctx, { kind: "syntaxCheck", ok: result.ok, count: results.length });
      return result;
    },

    async simulate(ctx = {}, options = {}) {
      return runOnce({ ...(ctx.options || {}), ...options, files: filesOf(ctx) });
    },

    async runtimeCheck(ctx = {}, options = {}) {
      const result = await runOnce({ ...(ctx.options || {}), ...options, files: filesOf(ctx) });
      record(ctx, { kind: "runtimeCheck", ok: result.ok !== false, entry: options.entry || ctx.entry });
      return result;
    },

    async rerun(ctx = {}) {
      return runOnce({ ...(ctx.options || {}), files: filesOf(ctx) });
    },

    async mutate(ctx = {}, next = {}) {
      ctx.options = { ...(ctx.options || {}), ...next };
      return runOnce(ctx.options);
    },

    async assertOk(ctx = {}, payload = {}) {
      const target = payload.path ? payload.path.split(".").reduce((acc, key) => acc?.[key], ctx) : ctx.result;
      const ok = target?.ok !== false;
      if (!ok && payload.throw !== false) throw new Error(payload.message || "Merkava assertion failed");
      return record(ctx, { kind: "assertOk", ok });
    }
  };
}

// B"H

import { evaluateCondition } from "../conditions/evaluateCondition.js";

function normalizeSteps(workflow = []) {
  if (Array.isArray(workflow)) return workflow;
  if (Array.isArray(workflow.steps)) return workflow.steps;
  return [];
}

async function runBranch(branch, ctx, actions) {
  if (!branch) return null;
  return executeWorkflow(Array.isArray(branch) ? branch : [branch], ctx, actions);
}

/**
 * B"H
 * Walks a declarative Merkava workflow. Each step is a small vessel: condition,
 * action, payload, optional `then`, optional `else`, and optional `onError`.
 * The Awtsmoos reveals the next state from the previous result without Chrome.
 *
 * @param {Array|Object} workflow Declarative steps or `{ steps }` wrapper.
 * @param {Object} ctx Mutable workflow context shared by all steps.
 * @param {Object<string, Function>} actions Action registry.
 * @returns {Promise<*>} Last meaningful step result.
 */
export async function executeWorkflow(workflow = [], ctx = {}, actions = {}) {
  const steps = normalizeSteps(workflow);
  let last = ctx.result ?? null;

  for (const step of steps) {
    if (!step || typeof step !== "object") continue;

    const passes = !step.condition || evaluateCondition(step.condition, ctx);
    if (!passes) {
      last = await runBranch(step.else, ctx, actions) ?? last;
      continue;
    }

    try {
      const action = actions[step.action];

      if (typeof action !== "function") {
        throw new Error(`Unknown Merkava workflow action: ${step.action || "<missing>"}`);
      }

      last = await action({ ...ctx, step, last }, step.payload || {});
      ctx.result = last;

      if (step.then) {
        last = await runBranch(step.then, ctx, actions) ?? last;
        ctx.result = last;
      }
    } catch (error) {
      ctx.error = {
        message: error.message,
        stack: error.stack,
        step: step.action || null
      };

      if (!step.onError) throw error;
      last = await runBranch(step.onError, ctx, actions) ?? ctx.error;
      ctx.result = last;
    }
  }

  return last;
}

// B"H

import { operators, getPath } from "./operators.js";

export function evaluateCondition(condition = {}, ctx = {}) {
  if (!condition || typeof condition !== "object") {
    return true;
  }

  const left = condition.path
    ? getPath(ctx, condition.path)
    : condition.left;

  const right = condition.right;
  const operator = operators[condition.operator || "eq"];

  if (!operator) {
    return false;
  }

  try {
    return !!operator(left, right, ctx);
  } catch (_) {
    return false;
  }
}
